-- =====================================================================
-- MIGRASI 0025 — POMPA MENGIKUTI KMK: INFUSION PUMP v3 & SYRINGE PUMP v2 (26 Okt 2026)
-- Supabase : qr-label-kalibrasi (PRODUKSI) — dijalankan setelah Ridhwan membalas "ikuti kmk semuanya ya, lanjutkan A"
--
-- Bahasa awam: "resep" kedua pompa diganti versi baru yang mengikuti metode kerja KMK-MK-053.0 / 095.0:
--   • Laik per titik aliran: |koreksi| ≤ 10 % dari setting (guard band w = U: ketidakpastian di kedua sisi saling coret)
--   • Penyumbatan Laik bila rata-rata < 20 psi; keselamatan listrik langsung dibanding ambang SNI IEC 62353
--   • Pengulangan 5 kali; titik aliran contoh KMK (Infusion 10/25/50/100/150, Syringe 10/25/50/75/100 mL/h)
-- Rumus rata-rata, koreksi, ketidakpastian (U95) TIDAK berubah. Versi lama hanya DINONAKTIFKAN (isinya tetap),
-- LKK yang sudah dibuat tetap memakai versi lamanya. Tidak ada tabel/kolom lama yang diubah.
-- =====================================================================

-- ===== BLOK 1 — BACKUP =====
create table backup.b20261026_tera_device_templates_0025 as table public.tera_device_templates;
select count(*) as template_tersalin from backup.b20261026_tera_device_templates_0025;

-- ===== BLOK 2 — PERUBAHAN =====
begin;
update public.tera_device_templates set aktif = false where kode_alat = 'infusion_pump' and versi = 2 and aktif;
update public.tera_device_templates set aktif = false where kode_alat = 'syringe_pump' and versi = 1 and aktif;
insert into public.tera_device_templates (kode_alat, nama, versi, kop, definition, aktif) values
  ('infusion_pump', 'Infusion Pump', 3, 'NON_KAN', '{"tipe":"pompa","kode_alat":"infusion_pump","nama":"Infusion Pump","versi":3,"sumber":"KMK-MK-053.0 (aturan keputusan guard band w = U, titik 10/25/50/100/150 mL/h, 5 pengulangan, occlusion < 20 psi) + rumus ketidakpastian Master_Infusion_Pump.xlsx (26 Okt 2026)","metode":"KMK-MK-053.0","kop":"NON_KAN","keselamatan_listrik":"wajib","identitas":{"resolusi":{"satuan":"mL/h","pilihan":[]},"jenisSkala":[],"jenisTetap":"Digital"},"identitasBidang":[{"id":"merek","label":"Merk Pabrik","jenis":"teks","maksPanjang":80},{"id":"tipe","label":"Tipe","jenis":"teks","maksPanjang":80},{"id":"noSeri","label":"No. Seri","jenis":"teks","maksPanjang":80},{"id":"rentangUkur","label":"Rentang Ukur (mis. 1 - 999 mL/h)","jenis":"teks","maksPanjang":40},{"id":"resolusi","label":"Resolusi","jenis":"angka","satuan":"mL/h"},{"id":"tanggalPenerimaan","label":"Tanggal penerimaan barang kalibrasi","jenis":"tanggal"},{"id":"ruang","label":"Ruangan","jenis":"teks","maksPanjang":80}],"standar":[{"peran":"ida","judul":"Infusion Device Analyzer (IDA)","parameter":["aliran_mlh","tekanan_psi"],"wajib":true},{"peran":"esa","judul":"Electrical Safety Analyzer (ESA)","parameter":["tegangan_v","resistansi_ohm","isolasi_mohm","arus_bocor_ua"],"wajib":true},{"peran":"termohigrometer","judul":"Termohigrometer","parameter":["suhu_c","kelembaban_rh"],"wajib":true,"hanyaRekomendasi":true}],"fisik":[{"id":"badan","judul":"Badan dan Permukaan / Enclosure and its Surfaces"},{"id":"kontrol","judul":"Kontrol dan Indikator / Control and indicator"},{"id":"kabel","judul":"Kabel dan Aksesori / Wire and acessories"}],"pilihanFisik":{"fisik":["Baik","Tidak Baik"],"fungsi":["Berfungsi","Tidak Berfungsi"]},"listrik":[{"id":"tegangan","judul":"Tegangan Catu Daya / Mains Voltage","satuan":"V","kalibrator":"tegangan","uji":{"jenis":"sekitar","nominal":220,"batas":22},"diBawahTabel":"ujung","toleransiTeks":"220 ±10 %"},{"id":"resistansi_pembumian","judul":"Resistansi Pembumian Protektif / Protective Earth Resistance","satuan":"Ω","kalibrator":"resistansi","uji":{"jenis":"maksimum","batas":0.3},"diBawahTabel":"ujung","toleransiTeks":"≤ 0,3"},{"id":"resistansi_isolasi","judul":"Isolasi Resistansi / Insulation of Resistance","satuan":"MΩ","kalibrator":"isolasi","uji":{"jenis":"minimum","batas":2},"diBawahTabel":"ujung","toleransiTeks":"≥ 2"},{"id":"arus_bocor","judul":"Arus Bocor Pembumian / Earth Leakage Current","satuan":"µA","kalibrator":"arus_bocor","uji":{"jenis":"maksimum","batas":500},"diBawahTabel":"proporsional","toleransiTeks":"≤ 500"}],"kinerja":{"titikAliran":[10,25,50,100,150],"pengulangan":5,"toleransiAliranPersen":0.1,"sumbat":{"batas":20,"banding":"<","resolusiTetap":0.01,"settingBawaan":100},"driftPersen":0.1,"derajatBebas":{"sertifikat":60,"resolusi":50,"drift":50},"pembagiResolusi":{"Analog":2.449489742783178,"Digital":1.7320508075688772},"desimalCetak":2,"minimalPersenAliran":0.7},"skor":{"fisik":{"minimalPersen":0.7,"nilai":10},"listrik":{"nilai":40},"kinerja":{"nilai":50},"laikBila":{"banding":">=","batas":90}},"sertifikat":{"tata_letak":"report_all_infusion_pump","halaman":3},"aturanKeputusan":"guardband_w_u"}'::jsonb, true),
  ('syringe_pump', 'Syringe Pump', 2, 'NON_KAN', '{"tipe":"pompa","kode_alat":"syringe_pump","nama":"Syringe Pump","versi":2,"sumber":"KMK-MK-095.0 (aturan keputusan guard band w = U, titik 10/25/50/75/100 mL/h, 5 pengulangan, occlusion < 20 psi) + rumus ketidakpastian Master_Syringe_Pump_terisi.xlsx (26 Okt 2026)","metode":"KMK-MK-095.0","kop":"NON_KAN","keselamatan_listrik":"wajib","identitas":{"resolusi":{"satuan":"mL/h","pilihan":[]},"jenisSkala":[],"jenisTetap":"Digital"},"identitasBidang":[{"id":"merek","label":"Merk Pabrik","jenis":"teks","maksPanjang":80},{"id":"tipe","label":"Tipe","jenis":"teks","maksPanjang":80},{"id":"noSeri","label":"No. Seri","jenis":"teks","maksPanjang":80},{"id":"rentangUkur","label":"Rentang Ukur (mis. 0,1 - 99,9 mL/h)","jenis":"teks","maksPanjang":40},{"id":"resolusi","label":"Resolusi","jenis":"angka","satuan":"mL/h"},{"id":"tanggalPenerimaan","label":"Tanggal penerimaan barang kalibrasi","jenis":"tanggal"},{"id":"ruang","label":"Ruangan","jenis":"teks","maksPanjang":80}],"standar":[{"peran":"ida","judul":"Infusion Device Analyzer (IDA)","parameter":["aliran_mlh","tekanan_psi"],"wajib":true},{"peran":"esa","judul":"Electrical Safety Analyzer (ESA)","parameter":["tegangan_v","resistansi_ohm","isolasi_mohm","arus_bocor_ua"],"wajib":true},{"peran":"termohigrometer","judul":"Termohigrometer","parameter":["suhu_c","kelembaban_rh"],"wajib":true,"hanyaRekomendasi":true}],"fisik":[{"id":"badan","judul":"Badan dan Permukaan / Enclosure and its Surfaces"},{"id":"kontrol","judul":"Kontrol dan Indikator / Control and indicator"},{"id":"kabel","judul":"Kabel dan Aksesori / Wire and acessories"}],"pilihanFisik":{"fisik":["Baik","Tidak Baik"],"fungsi":["Berfungsi","Tidak Berfungsi"]},"listrik":[{"id":"tegangan","judul":"Tegangan Catu Daya / Mains Voltage","satuan":"V","kalibrator":"tegangan","uji":{"jenis":"sekitar","nominal":220,"batas":22},"diBawahTabel":"ujung","toleransiTeks":"220 ±10 %"},{"id":"resistansi_pembumian","judul":"Resistansi Pembumian Protektif / Protective Earth Resistance","satuan":"Ω","kalibrator":"resistansi","uji":{"jenis":"maksimum","batas":0.3},"diBawahTabel":"ujung","toleransiTeks":"≤ 0,3"},{"id":"resistansi_isolasi","judul":"Isolasi Resistansi / Insulation of Resistance","satuan":"MΩ","kalibrator":"isolasi","uji":{"jenis":"minimum","batas":2},"diBawahTabel":"ujung","toleransiTeks":"≥ 2"},{"id":"arus_bocor","judul":"Arus Bocor Pembumian / Earth Leakage Current","satuan":"µA","kalibrator":"arus_bocor","uji":{"jenis":"maksimum","batas":500},"diBawahTabel":"proporsional","toleransiTeks":"≤ 500"}],"kinerja":{"titikAliran":[10,25,50,75,100],"pengulangan":5,"toleransiAliranPersen":0.1,"sumbat":{"batas":20,"banding":"<","resolusiTetap":0.01,"settingBawaan":100},"driftPersen":0.1,"derajatBebas":{"sertifikat":60,"resolusi":50,"drift":50},"pembagiResolusi":{"Analog":2.449489742783178,"Digital":1.7320508075688772},"desimalCetak":2,"minimalPersenAliran":0.7,"aturanAliran":"u95"},"skor":{"fisik":{"minimalPersen":0.7,"nilai":10},"listrik":{"nilai":40},"kinerja":{"nilai":50},"laikBila":{"banding":">=","batas":90}},"sertifikat":{"tata_letak":"report_all_syringe_pump","halaman":3},"aturanKeputusan":"guardband_w_u"}'::jsonb, true);
commit;

-- ===== BLOK 3 — CEK (harapan: semua true) =====
select 'versi baru aktif, versi lama nonaktif' cek,
       (select count(*) = 2 from public.tera_device_templates where aktif and ((kode_alat='infusion_pump' and versi=3) or (kode_alat='syringe_pump' and versi=2)))
       and (select count(*) = 0 from public.tera_device_templates where aktif and ((kode_alat='infusion_pump' and versi<3) or (kode_alat='syringe_pump' and versi<2))) hasil
union all select 'aturan KMK: guard band, 5 pengulangan, occlusion <',
       (select bool_and(definition->>'aturanKeputusan' = 'guardband_w_u' and (definition->'kinerja'->>'pengulangan')::int = 5 and definition->'kinerja'->'sumbat'->>'banding' = '<')
          from public.tera_device_templates where (kode_alat='infusion_pump' and versi=3) or (kode_alat='syringe_pump' and versi=2))
union all select 'titik KMK',
       (select definition->'kinerja'->'titikAliran' = '[10,25,50,100,150]'::jsonb from public.tera_device_templates where kode_alat='infusion_pump' and versi=3)
       and (select definition->'kinerja'->'titikAliran' = '[10,25,50,75,100]'::jsonb from public.tera_device_templates where kode_alat='syringe_pump' and versi=2)
union all select 'isi template lama tidak berubah',
       (select count(*) = 0 from public.tera_device_templates t join backup.b20261026_tera_device_templates_0025 b using (id) where t.definition <> b.definition);

